from concurrent.futures import ThreadPoolExecutor
import sys
import threading

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Run check on every element of xs in parallel using a thread pool.

    Returns the checked values in input order. If any element is bad,
    raises the Bad for the lowest-index bad element, regardless of which
    thread finishes first.
    """
    with ThreadPoolExecutor() as pool:
        futures = [pool.submit(check, x) for x in xs]
        results: list[int] = []
        # Collect in input order: the first future that raised is the
        # lowest-index bad element, whatever order the threads finished in.
        for fut in futures:
            results.append(fut.result())
    return results


def test_all_even_returns_values_in_order() -> None:
    xs = [2, 4, 6, 8, 10, 0, -2]
    assert all_even(xs) == xs


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_single_bad() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 4, 7, 8])
    assert ei.value.n == 7


def test_all_even_lowest_index_wins_simple() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 9, 4, 3, 5])
    assert ei.value.n == 9


def test_all_even_lowest_index_wins_even_if_finishes_last(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    orig = check
    later_bad_raised = threading.Event()

    def slow_check(x: int) -> int:
        if x == 3:
            # Lowest-index bad element: finish only after the later bad one.
            later_bad_raised.wait(timeout=2.0)
            return orig(x)
        if x == 5:
            try:
                return orig(x)
            finally:
                later_bad_raised.set()
        return orig(x)

    monkeypatch.setattr(sys.modules[__name__], "check", slow_check)
    with pytest.raises(Bad) as ei:
        all_even([2, 3, 4, 5])
    assert ei.value.n == 3


def test_all_even_runs_in_parallel(monkeypatch: pytest.MonkeyPatch) -> None:
    barrier = threading.Barrier(2, timeout=2.0)
    orig = check

    def barrier_check(x: int) -> int:
        barrier.wait()
        return orig(x)

    monkeypatch.setattr(sys.modules[__name__], "check", barrier_check)
    assert all_even([2, 4]) == [2, 4]

